PACKET=json.loads('{"normal107_custody_bridge.py":{"bytes":7363,"sha256":"6e0803628e858259f22836790e970248da205fdd848d52e6fbcb521fce6062ef","source":"\\"\\"\\"Keep the unchanged Linux campaign under original-child process custody.\\n\\nThe caller pins all sources. This module grants no storage or service authority.\\nThe admission callback is invoked once; the original controller is compiled and\\nexecuted verbatim. Its SystemExit is caught inside the existing custody context\\nso an exit code of zero cannot conceal unfinished children or a custody gap.\\n\\"\\"\\"\\nimport time\\n\\n\\ndef execute(admission_source, admission_filename, controller_source,\\n            controller_filename, custody, *, deadline):\\n    namespace = None\\n    owner = None\\n    called = 0\\n    exit_code = None\\n    exception_type = None\\n\\n    def run_controller():\\n        nonlocal namespace, called, exit_code, exception_type\\n        called += 1\\n        if called != 1 or time.monotonic() >= deadline:\\n            raise RuntimeError(\'single_controller_before_original_deadline_required\')\\n        namespace = {\'__name__\': \'__main__\', \'__file__\': controller_filename}\\n        try:\\n            exec(compile(controller_source, controller_filename, \'exec\'), namespace)\\n        except SystemExit as error:\\n            exit_code = 0 if error.code is None else error.code\\n        except BaseException as error:\\n            exception_type = type(error).__name__\\n        else:\\n            exception_type = \'MissingOriginalSystemExit\'\\n\\n    try:\\n        with custody.activated() as current:\\n            owner = current\\n            admission = {\'__name__\': \'__main__\', \'__file__\': admission_filename,\\n                         \'RUN_CURRENT_CONTROLLER\': run_controller}\\n            exec(compile(admission_source, admission_filename, \'exec\'), admission)\\n            if called != 1:\\n                raise RuntimeError(\'admission_did_not_invoke_one_controller\')\\n            current.assert_retired()\\n    except BaseException as error:\\n        exception_type = exception_type or type(error).__name__\\n    receipt = None if owner is None else owner.receipt()\\n    closed = receipt is not None and receipt.get(\'finished\') is True and all(\\n        row.get(\'original_wait_count\') == 1\\n        and row.get(\'original_wait_completed\') is True\\n        and row.get(\'no_live_members_before_reap\') is True\\n        for row in receipt.get(\'children\', []))\\n    passed = (called == 1 and type(exit_code) is int and exit_code == 0\\n              and exception_type is None and closed\\n              and receipt.get(\'passed_process_custody\') is True\\n              and time.monotonic() < deadline)\\n    observation = {\\n        \'schema\': \'heptabao.normal107-original-controller-custody.v1\',\\n        \'controller_invocations\': called, \'controller_native_exit_code\':\\n            exit_code if type(exit_code) is int else None,\\n        \'exception_type\': exception_type, \'process_custody\': receipt,\\n        \'originals_closed\': closed, \'remote_closure_unknown\': not closed,\\n        \'passed_controller_exit_and_custody\': passed,\\n        \'controller_result_validation_required_separately\': True,\\n        \'controller_functions_or_workload_modified\': False,\\n        \'deadline_renewed\': False,\\n    }\\n    return observation, namespace\\n\\n\\ndef require_current_result(value, selection, commit, tree):\\n    \\"\\"\\"Bind the independently read original result to the full selected cohort.\\"\\"\\"\\n    groups = selection[\'legacy_groups\'] + selection[\'legacy_additional_groups\'] + selection[\'added_groups\']\\n    names = [name for group in groups for name in group[\'tests\']]\\n    if (selection[\'execution_source_commit\'] != commit\\n            or selection[\'execution_source_tree\'] != tree\\n            or len(names) != 107 or len(set(names)) != 107\\n            or value.get(\'schema\') != \'heptabao.convergence-normal-build-tests.v1\'\\n            or value.get(\'status\') != \'passed\' or value.get(\'failure\') is not None\\n            or value.get(\'source_commit\') != commit or value.get(\'source_tree\') != tree\\n            or value.get(\'passed_cases\') != 107 or value.get(\'executed_passed_cases\') != 107\\n            or value.get(\'not_qualified_cases\') != 0\\n            or value.get(\'source_and_artifacts_unchanged\') is not True\\n            or value.get(\'outer_budget_seconds\') != 12000\\n            or value.get(\'deadline_renewed\') is not False\\n            or value.get(\'build_environment_overrides\') != selection[\'original_build\'][\'env\']\\n            or value.get(\'expected_denominators\') != selection[\'denominators\']):\\n        raise RuntimeError(\'exact_current_normal107_result_required\')\\n    actual = value.get(\'groups\')\\n    if type(actual) is not list or len(actual) != len(groups):\\n        raise RuntimeError(\'complete_original_groups_required\')\\n    for expected, row in zip(groups, actual):\\n        enumeration = value.get(\'enumeration\', {}).get(expected[\'label\'], {})\\n        if (row.get(\'label\') != expected[\'label\'] or row.get(\'status\') != \'passed\'\\n                or row.get(\'crate\') != expected[\'crate\']\\n                or row.get(\'tests\') != expected[\'tests\']\\n                or row.get(\'expected_count\') != expected[\'expected_count\']\\n                or row.get(\'passed\') != expected[\'expected_count\']\\n                or row.get(\'original_group_budget_seconds\') != expected[\'runtime_seconds\']\\n                or row.get(\'budget_renewed_per_case\') is not False\\n                or enumeration.get(\'matched_count\') != expected[\'expected_count\']\\n                or enumeration.get(\'matched_names\') != sorted(expected[\'tests\'])\\n                or type(row.get(\'results\')) is not list or not row[\'results\']):\\n            raise RuntimeError(\'complete_exact_original_group_results_required\')\\n        suffixes = expected.get(\'argv_suffixes\', [expected.get(\'argv_suffix\')])\\n        per_result = 1 if len(suffixes) > 1 or expected.get(\'selection_mode\') == \'per-test-exact\' else expected[\'expected_count\']\\n        if len(row[\'results\']) != len(suffixes):\\n            raise RuntimeError(\'all_exact_original_invocations_required\')\\n        for result in row[\'results\']:\\n            if (result.get(\'exact_denominator_passed\') is not True\\n                    or result.get(\'reported_state\') != \'ok\'\\n                    or any(type(result.get(k)) is not int for k in\\n                           (\'passed\', \'failed\', \'ignored\', \'measured\', \'filtered_out\'))\\n                    or result[\'passed\'] != per_result\\n                    or any(result[k] != 0 for k in (\'failed\', \'ignored\', \'measured\'))\\n                    or result[\'filtered_out\'] < 0):\\n                raise RuntimeError(\'no_failed_ignored_measured_or_missing_cases\')\\n    steps = value.get(\'steps\')\\n    if type(steps) is not list or not steps or any(\\n            step.get(\'exit_code\') != 0 or step.get(\'timed_out\') is not False\\n            or \'exception_type\' in step\\n            or step.get(\'owned_group_cleanup\', {}).get(\'all_owned_processes_gone\') is not True\\n            or step.get(\'unexpected_live_descendants_on_success\') is True for step in steps):\\n        raise RuntimeError(\'all_original_steps_and_group_closures_required\')\\n    for when in (\'old_retained_artifacts_before\', \'old_retained_artifacts_after\'):\\n        observed = value.get(when)\\n        if type(observed) is not dict or set(observed) != set(selection[\'old_retained_artifacts\']):\\n            raise RuntimeError(\'complete_retained_input_map_required\')\\n        if any(row.get(\'matches_original\') is not True for row in observed.values()):\\n            raise RuntimeError(\'all_retained_inputs_unchanged_required\')\\n    return True\\n"},"qualify_normal107_custody_bridge.py":{"bytes":7019,"sha256":"8be99da82f0c2cea28b0b6913e267560909a6008752033e220e3e8a6bf645316","source":"\\"\\"\\"Bounded real Linux children for the new custody bridge, never Rust or product tests.\\"\\"\\"\\nimport ast\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport signal\\nimport sys\\nimport time\\n\\n\\ndef qualify(bridge, custody, controller_source, directory, outcomes=None):\\n    began = time.monotonic()\\n    deadline = began + 30\\n    syscall_events = []\\n    signal_probe = None\\n    def audit(event, args):\\n        nonlocal signal_probe\\n        if event == \'heptabao.qualification.signal_probe_begin\':\\n            if signal_probe is not None or args not in ((\'post_wait\',), (\'unknown_group\',)):\\n                raise RuntimeError(\'invalid_local_signal_probe_begin\')\\n            signal_probe = args[0]\\n        elif event == \'heptabao.qualification.signal_probe_end\':\\n            if args != (signal_probe,) or signal_probe is None:\\n                raise RuntimeError(\'invalid_local_signal_probe_end\')\\n            signal_probe = None\\n        if event in (\'os.killpg\', \'os.kill\'):\\n            syscall_events.append({\'event\': event, \'target\': args[0], \'signal\': int(args[1]),\\n                                   \'probe_guard_blocked_before_kernel\': signal_probe is not None})\\n            if signal_probe is not None:\\n                raise RuntimeError(\'invalid_signal_probe_blocked_before_kernel\')\\n    sys.addaudithook(audit)\\n    selected = {\'Failed\', \'need\', \'process_group\', \'clean_owned_group\', \'digest\',\\n                \'publish\', \'checkpoint\', \'run_step\'}\\n    nodes = ast.parse(controller_source).body\\n    pieces = [ast.get_source_segment(controller_source, node) for node in nodes\\n              if isinstance(node, (ast.FunctionDef, ast.ClassDef)) and node.name in selected]\\n    if len(pieces) != len(selected):\\n        raise RuntimeError(\'exact_original_controller_functions_required\')\\n    original_functions = \'\\\\n\\\\n\'.join(pieces)\\n    if outcomes is None:\\n        outcomes = []\\n    elif type(outcomes) is not list or outcomes:\\n        raise RuntimeError(\'new_empty_outcome_list_required\')\\n    variants = [\\n        (\'closed_success\', \\"run_step(\'actual\', [sys.executable, \'-I\', \'-S\', \'-B\', \'-c\', \'print(1)\'], 2)\\\\nraise SystemExit(0)\\\\n\\", True),\\n        (\'timeout_rejected\', \\"try:\\\\n    run_step(\'actual\', [sys.executable, \'-I\', \'-S\', \'-B\', \'-c\', \'import signal,time;signal.signal(signal.SIGTERM,signal.SIG_IGN);time.sleep(10)\'], .2)\\\\nexcept Failed:\\\\n    raise SystemExit(1)\\\\nraise SystemExit(0)\\\\n\\", False),\\n        (\'post_wait_signal_rejected_without_syscall\', \\"run_step(\'actual\', [sys.executable, \'-I\', \'-S\', \'-B\', \'-c\', \'print(1)\'], 2)\\\\nsys.audit(\'heptabao.qualification.signal_probe_begin\',\'post_wait\')\\\\ntry:\\\\n    os.killpg(REPORT[\'steps\'][-1][\'pid\'], signal.SIGTERM)\\\\nfinally:\\\\n    sys.audit(\'heptabao.qualification.signal_probe_end\',\'post_wait\')\\\\nraise SystemExit(0)\\\\n\\", False),\\n        (\'unknown_group_rejected_without_syscall\', \\"run_step(\'actual\', [sys.executable, \'-I\', \'-S\', \'-B\', \'-c\', \'print(1)\'], 2)\\\\nsys.audit(\'heptabao.qualification.signal_probe_begin\',\'unknown_group\')\\\\ntry:\\\\n    os.killpg(2147483647, signal.SIGTERM)\\\\nfinally:\\\\n    sys.audit(\'heptabao.qualification.signal_probe_end\',\'unknown_group\')\\\\nraise SystemExit(0)\\\\n\\", False),\\n        (\'inner_zero_with_live_original_rejected\', \\"subprocess.Popen([sys.executable, \'-I\', \'-S\', \'-B\', \'-c\', \'import time;time.sleep(10)\'], stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)\\\\nraise SystemExit(0)\\\\n\\", False),\\n    ]\\n    for name, body, expected_pass in variants:\\n        if time.monotonic() >= deadline - 6:\\n            raise RuntimeError(\'qualification_original_deadline\')\\n        root = directory / name\\n        root.mkdir(mode=0o700)\\n        prologue = (\'import hashlib,json,os,re,signal,subprocess,sys,time\\\\nfrom pathlib import Path\\\\n\'\\n                    + \'OUT=Path(\' + repr(str(root)) + \');SOURCE=OUT\\\\n\'\\n                    + \\"ENV={\'PATH\':\'/usr/bin:/bin\'};REPORT={\'steps\':[]}\\\\n\\"\\n                    + \'START=time.monotonic();DEADLINE=START+38\\\\n\')\\n        text = prologue + original_functions + \'\\\\n\\\\n\' + body\\n        first = len(syscall_events)\\n        result, namespace = bridge.execute(\'RUN_CURRENT_CONTROLLER()\\\\n\', str(root/\'admission.fixture.py\'),\\n                                           text, str(root/\'controller.fixture.py\'), custody,\\n                                           deadline=min(deadline, time.monotonic()+8))\\n        observed = syscall_events[first:]\\n        receipt = result[\'process_custody\']\\n        children = receipt[\'children\']\\n        safe_closed = (len(children) == 1 and result[\'originals_closed\']\\n                       and not result[\'remote_closure_unknown\']\\n                       and children[0][\'original_wait_count\'] == 1\\n                       and children[0][\'original_wait_completed\']\\n                       and children[0][\'no_live_members_before_reap\'])\\n        correct = (result[\'passed_controller_exit_and_custody\'] is expected_pass\\n                   and safe_closed and signal_probe is None)\\n        if name in (\'post_wait_signal_rejected_without_syscall\', \'unknown_group_rejected_without_syscall\'):\\n            correct = correct and not observed and receipt[\'failed\'] is True\\n        if name == \'post_wait_signal_rejected_without_syscall\':\\n            correct = correct and any(x.get(\'outcome\') == \'already_retired_no_signal\'\\n                                      and x.get(\'group_signal_sent\') is False for x in receipt[\'controls\'])\\n        if name == \'unknown_group_rejected_without_syscall\':\\n            correct = correct and any(x.get(\'outcome\') == \'refused_unknown_original\'\\n                                      for x in receipt[\'controls\'])\\n        if name == \'timeout_rejected\':\\n            steps = namespace[\'REPORT\'][\'steps\']\\n            correct = correct and len(steps) == 1 and steps[0][\'timed_out\'] is True\\n            correct = correct and bool(observed) and all(x[\'target\'] == children[0][\'pid\'] for x in observed)\\n        if name == \'inner_zero_with_live_original_rejected\':\\n            correct = correct and result[\'controller_native_exit_code\'] == 0 and receipt[\'failed\'] is True\\n        outcomes.append({\'name\': name, \'passed\': bool(correct), \'expected_campaign_accepted\': expected_pass,\\n                         \'native_signal_syscalls\': observed, \'observation\': result})\\n        if not correct:\\n            raise RuntimeError(\'real_child_qualification_failed_\' + name)\\n    if time.monotonic() >= deadline:\\n        raise RuntimeError(\'qualification_original_deadline_after_closure\')\\n    return {\'schema\': \'heptabao.linux-normal107-custody-bridge-real-child-qualification.v1\',\\n            \'status\': \'passed\', \'platform\': sys.platform, \'cases\': outcomes,\\n            \'passed_cases\': len(outcomes), \'expected_cases\': 5,\\n            \'all_originals_closed\': all(x[\'observation\'][\'originals_closed\'] for x in outcomes),\\n            \'rust_build_executed\': False, \'product_binary_executions\': 0,\\n            \'normal107_qualified\': False, \'elapsed_seconds\': time.monotonic()-began,\\n            \'all_selected_original_functions_copied_verbatim\': True}\\n"},"controller.py":{"bytes":21718,"sha256":"aaee55e7b80ee4f55ee4518abd2ed4f881551eaa533afd9be316106ac39339a1","source":"#!/usr/bin/env python3\\n\\"\\"\\"One owned Pocket4 source/build/test attempt. No production service operations.\\"\\"\\"\\nimport fcntl\\nimport hashlib\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport re\\nimport shutil\\nimport signal\\nimport subprocess\\nimport sys\\nimport time\\n\\nos.umask(0o077)\\nROOT = Path(\'/home/alex/heptabao-kv2-ha-convergence-5f9d4-authbus-20261107-r2\')\\nSOURCE = ROOT / \'source-5f9d4\'\\nOUT = ROOT / \'build-test-r1\'\\nCOMMIT = \'5f9d4263b136685244aba93e45a69139cb8aba41\'\\nTREE = \'2c69f04159c112a883abe57f0d367a2627197c7a\'\\nPARENT = \'7d9e933d5ccab83d51c4de9ae7f028fe70e92302\'\\nOLD_HEAD = \'5f9d4263b136685244aba93e45a69139cb8aba41\'\\nFORMAT_PATCH = \'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\'\\nBUNDLE_SHA = \'e57a93e8f3c13f83259cc6f1a5ca1ddb2ebe8451a0da5ff677c38c83ee8d3d72\'\\nTOOLCHAIN = Path(\'/home/alex/.rustup/toolchains/1.98.0-x86_64-unknown-linux-gnu/bin\')\\nPINS = {\\n    \'cargo\': \'ff3022fcbd13b08434ea7afde9a0ef9d5b3f5c17b5fc7a40031be3ee000a6a24\',\\n    \'rustc\': \'3690cc576ede140504698405d5d8fa3826aaadbe71699c6c4ed0a565d6f493e2\',\\n    \'rustfmt\': \'5005cdcd39ded526dca8fa6ccd716d42fc7da54469034e055dbf54649bec7877\',\\n}\\nSTART = time.monotonic()\\nDEADLINE = START + 12000\\nMANIFEST = json.loads((OUT / \'test-selection.public.json\').read_text())\\nENV = {key: os.environ[key] for key in (\'HOME\', \'USER\', \'LOGNAME\', \'LANG\', \'LC_ALL\', \'TMPDIR\', \'TZ\')\\n       if key in os.environ}\\nENV.update(MANIFEST[\'original_build\'][\'env\'])\\nENV.update(RUSTC=str(TOOLCHAIN / \'rustc\'), RUSTFMT=str(TOOLCHAIN / \'rustfmt\'),\\n           RUSTC_WRAPPER=\'\', RUSTC_WORKSPACE_WRAPPER=\'\',\\n           CARGO_BUILD_RUSTC_WRAPPER=\'\', CARGO_BUILD_RUSTC_WORKSPACE_WRAPPER=\'\')\\nREPORT = {\\n    \'schema\': \'heptabao.convergence-normal-build-tests.v1\',\\n    \'status\': \'running\', \'source_commit\': COMMIT, \'source_tree\': TREE,\\n    \'source_parent\': PARENT, \'created_at_unix\': time.time(),\\n    \'outer_budget_seconds\': 12000, \'deadline_renewed\': False,\\n    \'toolchain_pins\': PINS, \'build_environment_overrides\': MANIFEST[\'original_build\'][\'env\'],\\n    \'expected_denominators\': MANIFEST[\'denominators\'],\\n    \'steps\': [], \'artifacts\': {}, \'groups\': [], \'enumeration\': {},\\n    \'production_changed\': False, \'production_server_started\': False,\\n    \'formal_kv2_qualified\': False, \'physical_ha_qualified\': False,\\n    \'authbus_migration_qualified\': False, \'full_replacement_qualified\': False,\\n    \'automatic_retry\': False, \'failure\': None,\\n    \'ambient_build_overrides_inherited\': False,\\n    \'explicit_compiler\': str(TOOLCHAIN / \'rustc\'), \'compiler_wrappers_disabled\': True,\\n}\\n\\n\\nclass Failed(RuntimeError):\\n    pass\\n\\n\\nclass Interrupted(BaseException):\\n    pass\\n\\n\\ndef interrupted(signum, _frame):\\n    raise Interrupted(signum)\\n\\n\\nsignal.signal(signal.SIGTERM, interrupted)\\nsignal.signal(signal.SIGINT, interrupted)\\n\\n\\ndef process_group(pgid):\\n    rows = []\\n    for path in Path(\'/proc\').iterdir():\\n        if not path.name.isdigit():\\n            continue\\n        try:\\n            fields = (path / \'stat\').read_text().rsplit(\')\', 1)[1].split()\\n            if int(fields[2]) == pgid and int(fields[3]) == pgid:\\n                rows.append({\'pid\': int(path.name), \'state\': fields[0],\\n                             \'pgrp\': int(fields[2]), \'session\': int(fields[3]),\\n                             \'start_ticks\': int(fields[19])})\\n        except (OSError, ValueError, IndexError):\\n            continue\\n    return rows\\n\\n\\ndef clean_owned_group(proc, leader_start, abnormal):\\n    before = process_group(proc.pid)\\n    for row in before:\\n        need(row[\'start_ticks\'] >= leader_start, \'owned_group_identity_conflict\')\\n        if row[\'pid\'] == proc.pid:\\n            need(row[\'start_ticks\'] == leader_start, \'owned_group_leader_reused\')\\n    actions = []\\n    for sig, cap in ((signal.SIGTERM, 2), (signal.SIGKILL, 2)):\\n        rows = process_group(proc.pid)\\n        if not rows:\\n            break\\n        if any(row[\'state\'] != \'Z\' for row in rows):\\n            try:\\n                os.killpg(proc.pid, sig); actions.append(signal.Signals(sig).name)\\n            except ProcessLookupError:\\n                pass\\n        until = time.monotonic() + cap\\n        while time.monotonic() < until:\\n            proc.poll()\\n            if not process_group(proc.pid):\\n                break\\n            time.sleep(0.05)\\n    if proc.poll() is None:\\n        proc.wait(timeout=1)\\n    after = process_group(proc.pid)\\n    return {\'pgid\': proc.pid, \'leader_start_ticks\': leader_start,\\n            \'abnormal_exit\': abnormal, \'remaining_before_cleanup\': before,\\n            \'signals\': actions, \'remaining_after_cleanup\': after,\\n            \'all_owned_processes_gone\': not after}\\n\\n\\ndef digest(path):\\n    h = hashlib.sha256()\\n    with Path(path).open(\'rb\') as stream:\\n        for block in iter(lambda: stream.read(1024 * 1024), b\'\'):\\n            h.update(block)\\n    return h.hexdigest()\\n\\n\\ndef need(value, label):\\n    if not value:\\n        raise Failed(label)\\n\\n\\ndef publish(path, value):\\n    temp = path.with_suffix(path.suffix + \'.tmp\')\\n    with temp.open(\'w\') as stream:\\n        json.dump(value, stream, sort_keys=True, indent=2)\\n        stream.write(\'\\\\n\'); stream.flush(); os.fsync(stream.fileno())\\n    os.replace(temp, path)\\n\\n\\ndef checkpoint():\\n    REPORT[\'elapsed_seconds\'] = round(time.monotonic() - START, 3)\\n    publish(OUT / \'progress.public.json\', REPORT)\\n\\n\\ndef run_step(label, argv, seconds, *, end=None, allowed=(0,)):\\n    remaining = min(DEADLINE - 30, end if end is not None else DEADLINE) - time.monotonic()\\n    budget = min(seconds, remaining)\\n    need(budget > 0, label + \'_original_deadline_expired\')\\n    stdout = OUT / (label + \'.stdout\')\\n    stderr = OUT / (label + \'.stderr\')\\n    row = {\'step\': label, \'argv\': argv, \'requested_cap_seconds\': seconds,\\n           \'effective_budget_seconds\': round(budget, 6), \'attempts\': 1,\\n           \'timed_out\': False, \'started_at_unix\': time.time()}\\n    print(json.dumps({\'event\': \'step_started\', \'step\': label, \'budget_seconds\': round(budget, 3)}), flush=True)\\n    began = time.monotonic()\\n    proc = None\\n    leader_start = None\\n    with stdout.open(\'xb\') as so, stderr.open(\'xb\') as se:\\n        try:\\n            proc = subprocess.Popen(argv, cwd=SOURCE, env=ENV, stdin=subprocess.DEVNULL,\\n                                    stdout=so, stderr=se, start_new_session=True)\\n            row[\'pid\'] = proc.pid\\n            leader = [p for p in process_group(proc.pid) if p[\'pid\'] == proc.pid]\\n            need(len(leader) == 1, \'owned_leader_identity_unavailable\')\\n            leader_start = leader[0][\'start_ticks\']\\n            row[\'exit_code\'] = proc.wait(timeout=budget)\\n        except subprocess.TimeoutExpired:\\n            row[\'timed_out\'] = True\\n        except BaseException as error:\\n            row[\'exception_type\'] = type(error).__name__\\n        finally:\\n            if proc is not None:\\n                try:\\n                    need(leader_start is not None, \'owned_leader_identity_missing\')\\n                    cleanup = clean_owned_group(proc, leader_start,\\n                                                row[\'timed_out\'] or \'exception_type\' in row)\\n                    row[\'owned_group_cleanup\'] = cleanup\\n                    row[\'unexpected_live_descendants_on_success\'] = (\\n                        row.get(\'exit_code\') == 0\\n                        and any(p[\'state\'] != \'Z\' for p in cleanup[\'remaining_before_cleanup\']))\\n                except BaseException as error:\\n                    row[\'owned_group_cleanup\'] = {\'all_owned_processes_gone\': False,\\n                                                  \'cleanup_error_type\': type(error).__name__}\\n                row[\'exit_code\'] = proc.returncode\\n            else:\\n                row[\'exit_code\'] = None\\n                row[\'owned_group_cleanup\'] = {\'all_owned_processes_gone\': True, \'child_started\': False}\\n            so.flush(); se.flush(); os.fsync(so.fileno()); os.fsync(se.fileno())\\n    row.update(seconds=round(time.monotonic() - began, 6),\\n               stdout_bytes=stdout.stat().st_size, stderr_bytes=stderr.stat().st_size,\\n               stdout_sha256=digest(stdout), stderr_sha256=digest(stderr))\\n    REPORT[\'steps\'].append(row)\\n    publish(OUT / (label + \'.public.json\'), row)\\n    checkpoint()\\n    print(json.dumps({\'event\': \'step_finished\', \'step\': label, \'exit_code\': row[\'exit_code\'],\\n                      \'timed_out\': row[\'timed_out\'], \'seconds\': row[\'seconds\']}), flush=True)\\n    need(not row[\'timed_out\'] and \'exception_type\' not in row and row[\'exit_code\'] in allowed\\n         and row[\'owned_group_cleanup\'][\'all_owned_processes_gone\']\\n         and not row.get(\'unexpected_live_descendants_on_success\'), label + \'_failed\')\\n    return stdout\\n\\n\\ndef git(label, args, cap=30):\\n    return run_step(label, [\'/usr/bin/git\', *args], cap).read_text().strip()\\n\\n\\ndef resources():\\n    mem = dict((line.split(\':\')[0], int(line.split()[1]))\\n               for line in Path(\'/proc/meminfo\').read_text().splitlines()\\n               if line.startswith((\'MemAvailable:\', \'SwapFree:\')))\\n    compilers = []\\n    for path in Path(\'/proc\').iterdir():\\n        if not path.name.isdigit():\\n            continue\\n        try:\\n            name = (path / \'comm\').read_text().strip()\\n        except OSError:\\n            continue\\n        if name in {\'cargo\', \'rustc\', \'rustfmt\', \'rust-lld\'}:\\n            compilers.append({\'pid\': int(path.name), \'comm\': name})\\n    return {\'disk_free_bytes\': shutil.disk_usage(ROOT).free,\\n            \'mem_available_kib\': mem[\'MemAvailable\'], \'swap_free_kib\': mem[\'SwapFree\'],\\n            \'load_average\': list(os.getloadavg()), \'compiler_processes\': compilers}\\n\\n\\ndef retain_artifact(json_path, label, target_name, test):\\n    found = []\\n    for line in json_path.read_text().splitlines():\\n        try:\\n            item = json.loads(line)\\n        except json.JSONDecodeError:\\n            continue\\n        if (item.get(\'reason\') == \'compiler-artifact\'\\n            and item.get(\'target\', {}).get(\'name\') == target_name\\n            and item.get(\'profile\', {}).get(\'test\') is test and item.get(\'executable\')):\\n            found.append(item)\\n    need(len(found) == 1, label + \'_unambiguous_cargo_artifact\')\\n    item = found[0]; source = Path(item[\'executable\'])\\n    package = \'heptabao-ha-service\' if target_name == \'heptabao_ha_service\' else \'heptabao-server\'\\n    expected_features = ([\'default\', \'native-v6-peer-ingress\'] if package == \'heptabao-ha-service\'\\n                         else [\'default\', \'native-v6-ha\', \'native-v6-storage\'])\\n    need(sorted(item.get(\'features\', [])) == sorted(expected_features), label + \'_normal_features\')\\n    expected_profile = {\'opt_level\': \'3\', \'debuginfo\': 0, \'debug_assertions\': True,\\n                        \'overflow_checks\': True, \'test\': test}\\n    need(all(item.get(\'profile\', {}).get(k) == v for k, v in expected_profile.items()),\\n         label + \'_normal_profile\')\\n    expected_entry = (\'src/lib.rs\' if test else\\n                      \'src/bin/heptabao-seed.rs\' if target_name == \'heptabao-seed\' else \'src/main.rs\')\\n    package_root = SOURCE / \'crates\' / package\\n    need(Path(item.get(\'target\', {}).get(\'src_path\', \'\')).resolve() == package_root / expected_entry,\\n         label + \'_source_entry\')\\n    need(item.get(\'package_id\', \'\').startswith(\'path+file://\' + str(package_root) + \'#\'),\\n         label + \'_source_package\')\\n    target = OUT / \'artifacts\' / label\\n    need(source.is_file() and not source.is_symlink(), label + \'_regular_file\')\\n    before = digest(source)\\n    with source.open(\'rb\') as src, target.open(\'xb\') as dst:\\n        shutil.copyfileobj(src, dst, 1024 * 1024)\\n        dst.flush(); os.fsync(dst.fileno())\\n    target.chmod(0o700)\\n    need(before == digest(target) == digest(source), label + \'_copy_hash\')\\n    REPORT[\'artifacts\'][label] = {\\n        \'path\': str(target), \'sha256\': before, \'bytes\': target.stat().st_size,\\n        \'source_commit\': COMMIT, \'source_tree\': TREE,\\n        \'cargo_features\': item.get(\'features\'), \'cargo_profile\': item.get(\'profile\'),\\n        \'cargo_fresh\': item.get(\'fresh\'), \'cargo_artifact_path\': str(source),\\n        \'cargo_source_entry\': item[\'target\'][\'src_path\'], \'cargo_package_id\': item[\'package_id\'],\\n        \'normal_features_profile_and_source_verified\': True,\\n    }\\n    checkpoint()\\n    return target\\n\\n\\ndef listed(label, binary):\\n    path = run_step(label + \'-list\', [str(binary), \'--list\'], 30)\\n    rows = [line[:-6] for line in path.read_text().splitlines() if line.endswith(\': test\')]\\n    need(rows and len(rows) == len(set(rows)), label + \'_listing_unique_nonzero\')\\n    return set(rows)\\n\\n\\ndef test_summary(path, expected):\\n    matches = re.findall(r\'test result: (ok|FAILED)\\\\. (\\\\d+) passed; (\\\\d+) failed; (\\\\d+) ignored; (\\\\d+) measured; (\\\\d+) filtered out;\', path.read_text())\\n    need(len(matches) == 1, \'single_libtest_result_required\')\\n    state, passed, failed, ignored, measured, filtered = matches[0]\\n    result = {\'passed\': int(passed), \'failed\': int(failed), \'ignored\': int(ignored),\\n              \'measured\': int(measured), \'filtered_out\': int(filtered)}\\n    result[\'exact_denominator_passed\'] = (state == \'ok\' and result[\'passed\'] == expected\\n        and result[\'failed\'] == 0 and result[\'ignored\'] == 0 and result[\'measured\'] == 0)\\n    result[\'reported_state\'] = state\\n    return result\\n\\n\\ndef execute_group(index, group, binary):\\n    started = time.monotonic()\\n    end = min(DEADLINE, started + group[\'runtime_seconds\'])\\n    row = {\'label\': group[\'label\'], \'crate\': group[\'crate\'], \'expected_count\': group[\'expected_count\'],\\n           \'original_group_budget_seconds\': group[\'runtime_seconds\'], \'budget_renewed_per_case\': False,\\n           \'tests\': group[\'tests\'], \'passed\': 0, \'results\': [], \'status\': \'running\'}\\n    REPORT[\'groups\'].append(row); checkpoint()\\n    suffixes = group.get(\'argv_suffixes\', [group.get(\'argv_suffix\')])\\n    for n, suffix in enumerate(suffixes):\\n        need(suffix is not None, \'test_argv_missing\')\\n        expected = 1 if len(suffixes) > 1 or group.get(\'selection_mode\') == \'per-test-exact\' else group[\'expected_count\']\\n        path = run_step(f\'test-{index:02d}-{group[\\"label\\"]}-{n:02d}\', [str(binary), *suffix],\\n                        group[\'runtime_seconds\'], end=end, allowed=(0, 101))\\n        result = test_summary(path, expected)\\n        row[\'results\'].append(result); checkpoint()\\n        need(result[\'exact_denominator_passed\'] and REPORT[\'steps\'][-1][\'exit_code\'] == 0,\\n             group[\'label\'] + \'_exact_test_result_failed\')\\n        row[\'passed\'] += result[\'passed\']; checkpoint()\\n    need(row[\'passed\'] == row[\'expected_count\'], group[\'label\'] + \'_count\')\\n    row[\'status\'] = \'passed\'; row[\'seconds\'] = round(time.monotonic() - started, 6); checkpoint()\\n\\n\\ndef main():\\n    need(MANIFEST[\'execution_source_commit\'] == COMMIT, \'selection_source_binding\')\\n    groups = MANIFEST[\'legacy_groups\'] + MANIFEST[\'legacy_additional_groups\'] + MANIFEST[\'added_groups\']\\n    names = [name for group in groups for name in group[\'tests\']]\\n    need(len(names) == len(set(names)) == 107, \'107_unique_selected_names\')\\n    need(sum(len(g[\'tests\']) for g in groups if g[\'crate\'] == \'heptabao-server\') == 90, \'server90\')\\n    for name, sha in PINS.items():\\n        need(digest(TOOLCHAIN / name) == sha, \'toolchain_pin_\' + name)\\n    REPORT[\'old_retained_artifacts_before\'] = old_artifacts()\\n    need(all(x[\'matches_original\'] for x in REPORT[\'old_retained_artifacts_before\'].values()),\\n         \'old_retained_artifact_preflight_changed\')\\n    REPORT[\'preflight\'] = resources(); checkpoint()\\n    need(not REPORT[\'preflight\'][\'compiler_processes\'], \'other_compiler_present\')\\n    need(REPORT[\'preflight\'][\'disk_free_bytes\'] >= 8 * 1024**3, \'build_disk_headroom\')\\n    need(REPORT[\'preflight\'][\'mem_available_kib\'] >= 12 * 1024**2, \'build_ram_headroom\')\\n    need(git(\'00-source-head\', [\'rev-parse\', \'HEAD\']) == OLD_HEAD, \'staged_original_head\')\\n    patch = run_step(\'01-preserved-format-diff\', [\'/usr/bin/git\', \'diff\', \'--binary\', \'HEAD\'], 30)\\n    need(digest(patch) == FORMAT_PATCH, \'exact_original_format_patch\')\\n    need(not git(\'02-untracked\', [\'ls-files\', \'--others\', \'--exclude-standard\']), \'untracked_source\')\\n    need(digest(OUT / \'candidate.bundle\') == BUNDLE_SHA, \'canonical_bundle_hash\')\\n    git(\'03-bundle-verify\', [\'bundle\', \'verify\', str(OUT / \'candidate.bundle\')])\\n    git(\'04-fetch\', [\'fetch\', str(OUT / \'candidate.bundle\'), \'HEAD\'])\\n    need(git(\'05-canonical-tree\', [\'rev-parse\', COMMIT + \'^{tree}\']) == TREE, \'canonical_tree\')\\n    need(git(\'06-canonical-parent\', [\'rev-parse\', COMMIT + \'^\']) == PARENT, \'canonical_parent\')\\n    git(\'07-stage-exact-format\', [\'add\', \'--update\'])\\n    need(git(\'08-format-working-tree\', [\'write-tree\']) == TREE, \'format_working_tree_matches_canonical\')\\n    git(\'09-checkout-canonical\', [\'checkout\', \'--detach\', COMMIT])\\n    need(not git(\'10-clean-source\', [\'status\', \'--porcelain\']), \'source_dirty_before_build\')\\n    git(\'11-fsck\', [\'fsck\', \'--full\', \'--strict\'], 60)\\n    run_step(\'12-format-check\', [str(TOOLCHAIN / \'cargo\'), \'fmt\', \'--all\', \'--\', \'--check\'], 60)\\n    (OUT / \'artifacts\').mkdir(mode=0o700)\\n    build = run_step(\'13-normal-release-build\', MANIFEST[\'build_examples\'][\'server_release\'], 1800)\\n    retain_artifact(build, \'heptabao-server\', \'heptabao-server\', False)\\n    retain_artifact(build, \'heptabao-seed\', \'heptabao-seed\', False)\\n    test_build = run_step(\'14-server-libtest-build\', MANIFEST[\'build_examples\'][\'server_libtest\'], 3600)\\n    server_tests = retain_artifact(test_build, \'heptabao-server-libtest\', \'heptabao_server\', True)\\n    peer_build = run_step(\'15-peer-libtest-build\', MANIFEST[\'build_examples\'][\'peer_libtest\'], 3600)\\n    peer_tests = retain_artifact(peer_build, \'heptabao-ha-service-libtest\', \'heptabao_ha_service\', True)\\n    binaries = {\'heptabao-server\': server_tests, \'heptabao-ha-service\': peer_tests}\\n    all_names = {crate: listed(crate, binary) for crate, binary in binaries.items()}\\n    for group in groups:\\n        expected = set(group[\'tests\']); available = all_names[group[\'crate\']]\\n        if group.get(\'selection_mode\') == \'per-test-exact\':\\n            selected = available.intersection(expected)\\n        elif group[\'exact\']:\\n            selected = {name for name in available if name == group[\'filter\']}\\n        else:\\n            selected = {name for name in available if group[\'filter\'] in name}\\n        need(selected == expected and len(selected) == group[\'expected_count\'], group[\'label\'] + \'_enumeration_mismatch\')\\n        REPORT[\'enumeration\'][group[\'label\']] = {\'matched_names\': sorted(selected), \'matched_count\': len(selected)}\\n    checkpoint()\\n    for index, group in enumerate(groups):\\n        execute_group(index, group, binaries[group[\'crate\']])\\n    need(sum(g[\'passed\'] for g in REPORT[\'groups\']) == 107, \'final107\')\\n    need(git(\'99-final-source-head\', [\'rev-parse\', \'HEAD\']) == COMMIT, \'source_head_changed\')\\n    need(not git(\'99-final-source-clean\', [\'status\', \'--porcelain\']), \'source_dirty_after_execution\')\\n    for artifact in REPORT[\'artifacts\'].values():\\n        need(digest(artifact[\'path\']) == artifact[\'sha256\'], \'retained_artifact_changed\')\\n    REPORT[\'source_and_artifacts_unchanged\'] = True\\n    REPORT[\'passed_cases\'] = 107\\n    need(time.monotonic() < DEADLINE, \'original_outer_deadline_expired\')\\n    REPORT[\'status\'] = \'passed\'\\n\\n\\ndef old_artifacts():\\n    result = {}\\n    for name, artifact in MANIFEST[\'old_retained_artifacts\'].items():\\n        path = Path(artifact[\'path\'])\\n        try:\\n            sha = digest(path); size = path.stat().st_size\\n            result[name] = {\'path\': str(path), \'sha256\': sha, \'bytes\': size,\\n                            \'matches_original\': sha == artifact[\'sha256\'] and size == artifact[\'bytes\']}\\n        except OSError as error:\\n            result[name] = {\'path\': str(path), \'matches_original\': False,\\n                            \'error_type\': type(error).__name__}\\n    return result\\n\\n\\nif __name__ == \'__main__\':\\n    lock = None\\n    try:\\n        target = Path(ENV[\'CARGO_TARGET_DIR\'])\\n        need(target.is_dir() and not target.is_symlink(), \'existing_build_cache_required\')\\n        lock = (target / \'.heptabao-convergence-exclusive.lock\').open(\'a\')\\n        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\\n        REPORT[\'selection_sha256\'] = digest(OUT / \'test-selection.public.json\')\\n        REPORT[\'controller_sha256\'] = digest(__file__)\\n        main()\\n    except BaseException as error:\\n        REPORT[\'status\'] = \'failed\'\\n        REPORT[\'failure\'] = str(error) if isinstance(error, Failed) else type(error).__name__\\n        if REPORT[\'groups\'] and REPORT[\'groups\'][-1][\'status\'] == \'running\':\\n            REPORT[\'groups\'][-1][\'status\'] = \'failed\'\\n    finally:\\n        REPORT[\'old_retained_artifacts_after\'] = old_artifacts()\\n        if not all(x[\'matches_original\'] for x in REPORT[\'old_retained_artifacts_after\'].values()):\\n            REPORT[\'status\'] = \'failed\'; REPORT[\'failure\'] = REPORT[\'failure\'] or \'old_retained_artifact_changed\'\\n        if time.monotonic() >= DEADLINE:\\n            REPORT[\'status\'] = \'failed\'; REPORT[\'failure\'] = REPORT[\'failure\'] or \'original_outer_deadline_expired\'\\n        REPORT[\'elapsed_seconds\'] = round(time.monotonic() - START, 6)\\n        REPORT[\'finished_at_unix\'] = time.time()\\n        REPORT[\'postflight\'] = resources()\\n        REPORT[\'executed_passed_cases\'] = sum(g[\'passed\'] for g in REPORT[\'groups\'])\\n        REPORT[\'not_qualified_cases\'] = 107 - REPORT[\'executed_passed_cases\']\\n        publish(OUT / \'result.public.json\', REPORT)\\n        checkpoint()\\n        print(json.dumps({\'event\': \'terminal\', \'status\': REPORT[\'status\'], \'failure\': REPORT[\'failure\'],\\n                          \'executed_passed_cases\': REPORT[\'executed_passed_cases\'],\\n                          \'result\': str(OUT / \'result.public.json\')}), flush=True)\\n        if lock is not None:\\n            lock.close()\\n    sys.exit(0 if REPORT[\'status\'] == \'passed\' else 1)\\n"}}')

class Refused(Exception):
    pass

def need(ok, code):
    if not ok:
        raise Refused(code)

def live():
    need(time.monotonic() < END - 10, 'original_preparation_deadline')

def identity(info):
    return tuple(getattr(info, k) for k in ('st_dev', 'st_ino', 'st_uid', 'st_gid',
                 'st_mode', 'st_nlink', 'st_size', 'st_mtime_ns', 'st_ctime_ns'))

def file_pin(path, expected=None, *, contents=False, maximum=128 * 1024 * 1024):
    live()
    path = Path(path)
    before = path.lstat()
    need(path.resolve(strict=True) == path and stat.S_ISREG(before.st_mode)
         and before.st_uid in (0, os.getuid()) and not before.st_mode & 0o022
         and before.st_nlink == 1 and 0 <= before.st_size <= maximum,
         'bounded_owned_regular_public_input')
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC)
    row = {'fd': fd, 'attempts': 0, 'closed': False}; FDS.append(row)
    try:
        need(identity(os.fstat(fd)) == identity(before), 'same_open_public_input')
        digest, size, raw = hashlib.sha256(), 0, bytearray()
        while True:
            live()
            part = os.read(fd, min(1048576, before.st_size + 1 - size))
            if not part:
                break
            size += len(part)
            need(size <= before.st_size, 'input_size_growth')
            digest.update(part)
            if contents:
                raw.extend(part)
        pin = (size, digest.hexdigest())
        need(size == before.st_size and identity(os.fstat(fd)) == identity(path.lstat()) == identity(before),
             'complete_public_input_unchanged')
        need(expected is None or pin == expected, 'exact_public_input_pin')
        PUBLIC.setdefault(path, (pin, identity(before)))
        return pin, bytes(raw)
    finally:
        row['attempts'] = 1
        os.close(fd); row['closed'] = True

def directory(path, private=False):
    info = path.lstat()
    need(path.resolve(strict=True) == path and stat.S_ISDIR(info.st_mode)
         and info.st_uid == os.getuid() and not info.st_mode & 0o022
         and (not private or stat.S_IMODE(info.st_mode) == 0o700), 'owned_canonical_directory')
    return identity(info)[:5]
